GLOSSARY = [
 ('Ablation','Ablação','Remover um componente mantendo os demais fixos para medir sua contribuição.'),
 ('Admission control','Controle de admissão','Decisão de aceitar trabalho conforme capacidade, quotas e orçamento disponíveis.'),
 ('Agent','Agente','Ciclo que escolhe ações usando observações, com ferramentas e condições de parada.'),
 ('At-least-once','Ao menos uma vez','Semântica de entrega que admite duplicatas e exige consumidor idempotente.'),
 ('Backpressure','Contrapressão','Controle que reduz ou recusa entrada quando consumidores estão saturados.'),
 ('Calibration','Calibração','Correspondência entre probabilidades declaradas e frequências observadas.'),
 ('Checkpoint','Ponto de retomada','Estado persistido de execução; não garante sozinho unicidade de efeitos externos.'),
 ('Chunk','Trecho','Unidade de conteúdo preparada para recuperação com metadados de origem.'),
 ('Context window','Janela de contexto','Limite de tokens processáveis numa execução, sujeito às regras do modelo.'),
 ('Cost attribution','Atribuição de custo','Associação de consumo a tenant, execução, agente, modelo e finalidade.'),
 ('Cross-encoder','Codificador conjunto','Modelo que avalia consulta e candidato juntos, frequentemente usado em reranking.'),
 ('Data leakage','Vazamento de dados de avaliação','Informação do teste que influencia treino ou seleção e torna métricas otimistas.'),
 ('Dead-letter queue','Fila de falhas','Armazenamento de mensagens que esgotaram tentativas e precisam de diagnóstico.'),
 ('Decoding','Decodificação','Geração de novos tokens a partir da representação e tokens anteriores.'),
 ('Drift','Mudança de distribuição','Alteração nas características dos dados ou relação com alvos ao longo do tempo.'),
 ('Embedding','Representação vetorial','Vetor aprendido; proximidade depende do modelo e não significa verdade.'),
 ('Fan-out / fan-in','Distribuição e reunião','Dividir trabalho em ramos e agregar resultados com regras explícitas.'),
 ('Groundedness','Fundamentação','Grau em que afirmações da resposta são sustentadas pelas evidências disponíveis.'),
 ('Hallucination','Alucinação','Conteúdo gerado não sustentado ou incorreto, apesar de poder parecer plausível.'),
 ('Idempotency','Idempotência','Repetir o mesmo pedido lógico preserva o mesmo efeito observável.'),
 ('Inference','Inferência','Uso de parâmetros treinados para produzir saída, sem necessariamente atualizar pesos.'),
 ('KV cache','Cache de chaves e valores','Estado de atenção reutilizado durante inferência, distinto de cache de respostas.'),
 ('Logit','Escore não normalizado','Valor antes da normalização para uma distribuição sobre tokens ou classes.'),
 ('PEP / PDP','Aplicador / decisor de política','O PDP decide autorização; o PEP impede ou permite o efeito.'),
 ('Prefill','Processamento da entrada','Etapa que processa tokens do prompt antes da geração autoregressiva.'),
 ('Prompt injection','Injeção de instruções','Tentativa de fazer dados ou mensagens alterarem indevidamente o comportamento do sistema.'),
 ('Recall','Revocação / cobertura','Fração dos itens relevantes que foram recuperados ou identificados.'),
 ('Reranking','Reordenação','Segunda avaliação de um conjunto de candidatos para melhorar ordem de relevância.'),
 ('Reservation','Reserva de orçamento','Bloqueio atômico de saldo para chamadas em andamento antes da cobrança conhecida.'),
 ('Semantic cache','Cache semântico','Reuso por similaridade de perguntas, que exige validação de equivalência e isolamento.'),
 ('Structured outputs','Saídas estruturadas','Formato restringido ou validado por schema; não prova correção factual ou autorização.'),
 ('Tenant','Organização isolada','Unidade de identidade, dados e política que não deve acessar recursos de outra.'),
 ('Throughput','Vazão','Quantidade de trabalho concluído por unidade de tempo, distinta de latência individual.'),
 ('Trace / span','Rastro / intervalo','Trace correlaciona a execução; span representa uma operação temporizada dentro dela.'),
 ('Usage metering','Medição de consumo','Registro de unidades consumidas, distinguindo estimativa de cobrança observada.'),
]

